    {"id": 2, "claim": "Both ships are traveling at the same speed.", "evidence": "Given in the problem statement.", "weight": 0.8, "depends_on": []},
    {"id": 3, "claim": "Momentum is defined as the product of mass and velocity ($p = mv$).", "evidence": "Standard physics definition of linear momentum.", "weight": 1.0, "depends_on": []},
    {"id": 4, "claim": "The ship with heavy cargo has greater momentum than the ship with light cargo.", "evidence": "Since masses differ ($m_{heavy} > m_{light}$) and velocities are equal ($v_{heavy} = v_{light}$), then $m_{heavy}v > m_{light}v$.", "weight": 1.0, "depends_on": [1, 2, 3]},
    {"id": 5, "claim": "To stop, the ship's momentum must be reduced to zero.", "evidence": "Stopping implies final velocity is zero, so final momentum is zero.", "weight": 0.9, "depends_on": []},
    {"id": 6, "claim": "The time required to stop depends on the change in momentum and the average stopping force ($\\Delta p = F \\Delta t$).", "evidence": "Impulse-Momentum Theorem.", "weight": 0.9, "depends_on": [5]},
    {"id": 7, "claim": "Assuming similar stopping forces (friction/drag) for identical ships, the ship with greater initial momentum requires more time to dissipate that momentum.", "evidence": "If $F$ is roughly constant or similar, a larger $\\Delta p$ requires a larger $\\Delta t$.", "weight": 1.0, "depends_on": [4, 6]}
  ],
  "answer": "B",
  "confidence": 0.95,
